    });
    console.log('Wrong pass status:', res.status); // should be 401

    // 3. Signin Avery
    res = await fetch(baseUrl + '/api/auth/signin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'avery@dropline.test', password: 'password123' })
    });
    const averyData = await res.json();
    console.log('Avery signed in:', averyData.user.name, 'rev:', averyData.gameState.revision, 'redWins:', averyData.gameState.redWins);
    const token = averyData.token;

    // 4. Avery Redo
    res = await fetch(baseUrl + '/api/game/redo', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token
      },
      body: JSON.stringify({ expectedRevision: averyData.gameState.revision, operationId: 'op-redo-1' })
    });
    const redoData = await res.json();
    console.log('Avery redo result: rev =', redoData.gameState.revision, 'curPlayer =', redoData.gameState.currentPlayer);

    // 5. Avery Idempotency check (send same operationId again)
    res = await fetch(baseUrl + '/api/game/redo', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token
      },
      body: JSON.stringify({ expectedRevision: averyData.gameState.revision, operationId: 'op-redo-1' })
    });
    const idempData = await res.json();
    console.log('Avery idempotency check rev =', idempData.gameState.revision); // should still be 8

    // 6. Avery Concurrency check (send stale expectedRevision)
    res = await fetch(baseUrl + '/api/game/move', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + token
      },
      body: JSON.stringify({ column: 1, expectedRevision: 7, operationId: 'op-move-stale' })
    });
    console.log('Stale move status:', res.status); // should be 409
    const staleData = await res.json();
    console.log('Stale message:', staleData.message);

    // 7. Avery Signout
    res = await fetch(baseUrl + '/api/auth/signout', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + token
      }
    });
    console.log('Signout status:', res.status);

    // 8. Next protected request with revoked token should fail (401)
    res = await fetch(baseUrl + '/api/game', {
      headers: {
        'Authorization': 'Bearer ' + token
      }
    });
    console.log('Revoked token status:', res.status); // should be 401

    // 9. Jordan Signin and check completed matches
    res = await fetch(baseUrl + '/api/auth/signin', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'jordan@dropline.test', password: 'password123' })
    });
    const jordanData = await res.json();
    console.log('Jordan total matches:', jordanData.archive.totalCount, 'matches returned:', jordanData.archive.matches.length);

    console.log('ALL BACKEND API TESTS PASSED SUCCESSFULLY!');
  } catch (err) {
    console.error('Test error:', err);
  } finally {
    server.close();
    if (fs.existsSync(testDbPath)) fs.unlinkSync(testDbPath);
  }
});
"

