/* ==========================================================================
   DropLine - Polished Connect Four Styles
   ========================================================================== */

:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --card-border: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;

  --color-board: #1e3a8a;
  --color-board-border: #172554;
  --color-slot: #0f172a;

  --color-red: #ef4444;
  --color-red-dark: #b91c1c;
  --color-red-glow: rgba(239, 68, 68, 0.4);

  --color-yellow: #f59e0b;
  --color-yellow-dark: #b45309;
  --color-yellow-glow: rgba(245, 158, 11, 0.4);

  --color-winning-glow: #38bdf8;
  --color-winning-ring: #fbbf24;

  --btn-primary: #3b82f6;
  --btn-primary-hover: #2563eb;
  --btn-secondary: #475569;
  --btn-secondary-hover: #334155;

  --focus-ring: #60a5fa;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body {
  min-height: 100%;
  background-color: var(--bg-color);
  color: var(--text-main);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* Accessibility Focus Ring */
:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

/* Layout Utilities */
.hidden {
  display: none !important;
}

.app-container {
  width: 100%;
  max-width: 1100px;
  margin: 0 auto;
  padding: 16px;
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

/* ==========================================================================
   Buttons & Inputs
   ========================================================================== */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 10px 16px;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
  user-select: none;
}

.btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.btn:active:not(:disabled) {
  transform: translateY(0);
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.btn-primary {
  background-color: var(--btn-primary);
  color: #ffffff;
}
.btn-primary:hover:not(:disabled) {
  background-color: var(--btn-primary-hover);
}

.btn-secondary {
  background-color: var(--btn-secondary);
  color: #ffffff;
}
.btn-secondary:hover:not(:disabled) {
  background-color: var(--btn-secondary-hover);
}

.btn-outline-secondary {
  background: transparent;
  border: 1px solid var(--card-border);
  color: var(--text-main);
}
.btn-outline-secondary:hover:not(:disabled) {
  background: var(--card-border);
}

.btn-block {
  width: 100%;
}

.btn-sm {
  padding: 6px 12px;
  font-size: 0.85rem;
  border-radius: var(--radius-sm);
}

.form-group {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
}

.form-group label {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
}

.form-control {
  width: 100%;
  padding: 10px 14px;
  background-color: #0f172a;
  border: 1px solid var(--card-border);
  border-radius: var(--radius-md);
  color: #ffffff;
  font-family: inherit;
  font-size: 1rem;
}
.form-control:focus {
  border-color: var(--btn-primary);
  outline: none;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.3);
}

/* ==========================================================================
   Sign-in View
   ========================================================================== */

.signin-view {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 80vh;
  padding: 16px 8px;
}

.signin-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  width: 100%;
  max-width: 440px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
  text-align: center;
}

.signin-header {
  margin-bottom: 24px;
}

.brand-badge {
  display: inline-block;
  background: rgba(59, 130, 246, 0.2);
  color: #60a5fa;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 4px 10px;
  border-radius: 9999px;
  margin-bottom: 8px;
}

.brand-title {
  font-size: 2.2rem;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.5px;
}

.brand-subtitle {
  color: var(--text-muted);
  font-size: 0.95rem;
  margin-top: 4px;
}

.alert {
  padding: 10px 14px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  margin-bottom: 16px;
  text-align: left;
}

.alert-danger {
  background-color: rgba(239, 68, 68, 0.2);
  border: 1px solid var(--color-red);
  color: #fca5a5;
}

.demo-accounts-card {
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--card-border);
  text-align: left;
}

.demo-accounts-card h2 {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 12px;
}

.demo-account-item {
  margin-bottom: 8px;
}
.demo-account-item button {
  width: 100%;
  text-align: left;
  justify-content: flex-start;
}

/* ==========================================================================
   Game Header
   ========================================================================== */

.game-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 16px;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-md);
  margin-bottom: 20px;
}

.game-header-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.brand-logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: #ffffff;
}

.game-mode-badge {
  font-size: 0.75rem;
  background: #334155;
  color: #cbd5e1;
  padding: 2px 8px;
  border-radius: 4px;
  font-weight: 600;
}

.game-header-meta {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.user-identity {
  display: flex;
  align-items: center;
  gap: 8px;
  background: #0f172a;
  padding: 6px 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--card-border);
}

.user-icon {
  font-size: 1.1rem;
}

.user-details {
  display: flex;
  flex-direction: column;
}

.user-name {
  font-size: 0.85rem;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.2;
}

.user-email {
  font-size: 0.75rem;
  color: var(--text-muted);
  line-height: 1.2;
}

.revision-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #0f172a;
  padding: 6px 10px;
  border-radius: var(--radius-md);
  border: 1px solid var(--card-border);
  font-size: 0.8rem;
}

.rev-label {
  color: var(--text-muted);
  font-weight: 500;
}

.rev-value {
  color: #60a5fa;
  font-weight: 700;
  font-family: monospace;
  font-size: 0.9rem;
}

/* ==========================================================================
   Main Game Layout
   ========================================================================== */

.game-main-content {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr);
  gap: 24px;
  align-items: start;
}

@media (max-width: 860px) {
  .game-main-content {
    grid-template-columns: 1fr;
  }
}

.arena-column {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.sidebar-column {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* ==========================================================================
   Scoreboard
   ========================================================================== */

.scoreboard {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 10px;
}

.score-card {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-md);
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
}

.score-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-bottom: 4px;
}
.dot-red { background: var(--color-red); box-shadow: 0 0 8px var(--color-red-glow); }
.dot-yellow { background: var(--color-yellow); box-shadow: 0 0 8px var(--color-yellow-glow); }
.dot-gray { background: #94a3b8; }

.score-title {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
}

.score-count {
  font-size: 1.4rem;
  font-weight: 800;
  color: #ffffff;
  margin-top: 2px;
}

/* ==========================================================================
   Turn & Feedback Panel
   ========================================================================== */

.status-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.turn-indicator {
  background: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  text-align: center;
  font-size: 1.25rem;
  font-weight: 800;
  color: #ffffff;
  transition: all 0.2s ease;
}

.turn-indicator.turn-red {
  border-color: var(--color-red);
  color: #fca5a5;
  background: rgba(239, 68, 68, 0.1);
}

.turn-indicator.turn-yellow {
  border-color: var(--color-yellow);
  color: #fde68a;
  background: rgba(245, 158, 11, 0.1);
}

.turn-indicator.turn-draw {
  border-color: #94a3b8;
  color: #e2e8f0;
  background: rgba(148, 163, 184, 0.1);
}

.feedback-banner {
  background: rgba(239, 68, 68, 0.2);
  border: 1px solid var(--color-red);
  color: #fca5a5;
  padding: 8px 12px;
  border-radius: var(--radius-md);
  font-size: 0.9rem;
  font-weight: 600;
  text-align: center;
}

/* ==========================================================================
   Board & Drop Controls
   ========================================================================== */

.board-wrapper {
  background: var(--color-board);
  border: 4px solid var(--color-board-border);
  border-radius: var(--radius-lg);
  padding: 12px;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.4), inset 0 2px 4px rgba(255, 255, 255, 0.15);
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.column-drop-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
  width: 100%;
}

.drop-btn {
  background: rgba(255, 255, 255, 0.15);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: var(--radius-sm);
  padding: 6px 2px;
  font-size: 0.75rem;
  font-weight: 700;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-height: 42px;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.drop-btn:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.3);
  transform: translateY(-2px);
}

.drop-btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 1px;
}

.drop-text {
  font-size: 0.65rem;
  line-height: 1.1;
  text-align: center;
}

.drop-arrow {
  font-size: 0.8rem;
  line-height: 1;
}

/* Connect Four Grid */
.connect-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  grid-template-rows: repeat(6, 1fr);
  gap: 6px;
  width: 100%;
  aspect-ratio: 7 / 6;
  background: var(--color-board);
}

.grid-cell {
  background-color: var(--color-slot);
  border-radius: 50%;
  width: 100%;
  height: 100%;
  aspect-ratio: 1 / 1;
  box-shadow: inset 0 4px 8px rgba(0, 0, 0, 0.6), inset 0 1px 2px rgba(0, 0, 0, 0.8);
  position: relative;
  transition: transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.grid-cell.cell-red {
  background: radial-gradient(circle at 35% 35%, #f87171 0%, var(--color-red) 60%, var(--color-red-dark) 100%);
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.4), inset 0 -3px 6px rgba(0, 0, 0, 0.4), 0 2px 4px rgba(0, 0, 0, 0.3);
}

.grid-cell.cell-yellow {
  background: radial-gradient(circle at 35% 35%, #fde047 0%, var(--color-yellow) 60%, var(--color-yellow-dark) 100%);
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.5), inset 0 -3px 6px rgba(0, 0, 0, 0.4), 0 2px 4px rgba(0, 0, 0, 0.3);
}

/* Winning Cell Highlight */
.grid-cell.cell-winning {
  box-shadow: 0 0 0 4px var(--color-winning-ring), 0 0 16px var(--color-winning-glow), inset 0 0 10px #ffffff;
  animation: pulse-winning 1.5s infinite alternate ease-in-out;
  z-index: 2;
}

.grid-cell.cell-winning::after {
  content: "★";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: #ffffff;
  font-size: clamp(14px, 3.5vw, 24px);
  text-shadow: 0 0 6px rgba(0,0,0,0.8);
}

@keyframes pulse-winning {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 3px var(--color-winning-ring), 0 0 12px var(--color-winning-glow);
  }
  100% {
    transform: scale(1.06);
    box-shadow: 0 0 0 5px #ffffff, 0 0 24px #38bdf8;
  }
}

/* ==========================================================================
   Toolbar
   ========================================================================== */

.action-toolbar {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.action-btn {
  padding: 12px 14px;
}

/* ==========================================================================
   Sidebar Panels (History & Archive)
   ========================================================================== */

.panel {
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  max-height: 400px;
}

.panel-header {
  padding: 12px 16px;
  border-bottom: 1px solid var(--card-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-title {
  font-size: 1rem;
