  font-weight: 700;
  color: var(--text-muted);
  width: 28px;
}

.history-move-player {
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 6px;
}

.history-move-player.color-Red {
  color: #f87171;
}

.history-move-player.color-Yellow {
  color: #fbbf24;
}

.history-move-coords {
  color: #cbd5e1;
  font-size: 0.8rem;
}

/* Archive List */
.archive-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.archive-card {
  background: #0f172a;
  border: 1px solid var(--card-border);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
