  gap: 2px;
}

.archive-result {
  font-size: 0.85rem;
  font-weight: 700;
}
.archive-result.res-red { color: #f87171; }
.archive-result.res-yellow { color: #fbbf24; }
.archive-result.res-draw { color: #cbd5e1; }

.archive-details {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* ==========================================================================
   Replay Modal
