  function restoreColumnFocus(col) {
    const btn = document.getElementById(`drop-col-${col}`);
    if (btn) {
      btn.focus();
    }
  }

  // Keyboard navigation for column drop controls
  function setupColumnKeyboardNav() {
    dropColBtns.forEach(btn => {
      const col = parseInt(btn.getAttribute('data-col'), 10);

      btn.addEventListener('click', () => {
        performMove(col);
      });

      btn.addEventListener('keydown', (e) => {
        if (e.key === 'ArrowLeft') {
          e.preventDefault();
          if (col > 1) {
            const prevBtn = document.getElementById(`drop-col-${col - 1}`);
            if (prevBtn) prevBtn.focus();
          }
        } else if (e.key === 'ArrowRight') {
          e.preventDefault();
          if (col < 7) {
            const nextBtn = document.getElementById(`drop-col-${col + 1}`);
            if (nextBtn) nextBtn.focus();
          }
        } else if (e.key === 'Home') {
          e.preventDefault();
          const firstBtn = document.getElementById('drop-col-1');
          if (firstBtn) firstBtn.focus();
        } else if (e.key === 'End') {
          e.preventDefault();
          const lastBtn = document.getElementById('drop-col-7');
          if (lastBtn) lastBtn.focus();
        } else if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          performMove(col);
        }
      });
    });
  }

  // Replay Modal Handlers
  function openReplay(match) {
    currentReplay = match;
    currentReplayStep = 0;

    replayModalTitle.textContent = 'Match Replay';
    replaySubtitle.textContent = `${match.result} • ${match.moveCount} moves`;

    replayRangeSlider.min = 0;
    replayRangeSlider.max = match.moves.length;
    replayRangeSlider.value = 0;

    renderReplayStep();
    replayModalOverlay.classList.remove('hidden');
    replayRangeSlider.focus();
  }

  function closeReplay() {
    currentReplay = null;
    replayModalOverlay.classList.add('hidden');
    if (lastTriggerElement && typeof lastTriggerElement.focus === 'function') {
      lastTriggerElement.focus();
    }
  }

  function setReplayStep(step) {
    if (!currentReplay) return;
    const max = currentReplay.moves.length;
    currentReplayStep = Math.max(0, Math.min(max, step));
    replayRangeSlider.value = currentReplayStep;
    renderReplayStep();
  }

  function renderReplayStep() {
    if (!currentReplay) return;

    const maxMoves = currentReplay.moves.length;
    const step = currentReplayStep;

    // Compute board state at this step
    const board = Array(42).fill('');
    for (let i = 0; i < step; i++) {
      const m = currentReplay.moves[i];
      board[m.index] = m.color;
    }

    const isFinal = (step === maxMoves);
    const winCells = (isFinal && currentReplay.winningCells) ? currentReplay.winningCells : [];

    // Render 42 grid cells
    replayBoardGrid.innerHTML = '';
    for (let row = 1; row <= 6; row++) {
      for (let col = 1; col <= 7; col++) {
        const index = (row - 1) * 7 + (col - 1);
        const color = board[index] || '';
        const isWinning = winCells.includes(index);

        const cellEl = document.createElement('div');
        cellEl.className = 'grid-cell';
        cellEl.setAttribute('role', 'gridcell');

        let ariaLabel = `Row ${row}, Column ${col}, ${color ? color : 'empty'}`;
        if (isWinning) {
          ariaLabel += ', winning';
          cellEl.classList.add('cell-winning');
        }

        if (color === 'Red') {
          cellEl.classList.add('cell-red');
        } else if (color === 'Yellow') {
          cellEl.classList.add('cell-yellow');
        }

        cellEl.setAttribute('aria-label', ariaLabel);
        replayBoardGrid.appendChild(cellEl);
      }
    }

    // Step Caption
    if (step === 0) {
      replayStepCaption.textContent = `Step 0 of ${maxMoves}: Starting empty board`;
    } else {
      const lastMove = currentReplay.moves[step - 1];
      let cap = `Move ${step} of ${maxMoves}: ${lastMove.color} in Col ${lastMove.column}, Row ${lastMove.row}`;
      if (isFinal) {
        cap += ` (${currentReplay.result})`;
      }
      replayStepCaption.textContent = cap;
    }

    // Buttons
    replayPrevBtn.disabled = (step === 0);
    replayNextBtn.disabled = (step === maxMoves);
  }

  // Setup Event Listeners
  function setupEvents() {
    // Sign in form
    signinForm.addEventListener('submit', handleSignIn);

    // Demo Fill Buttons
    demoFillBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        signinEmailInput.value = btn.getAttribute('data-email');
        signinPasswordInput.value = btn.getAttribute('data-password');
        signinSubmit();
      });
    });

    function signinSubmit() {
      handleSignIn();
    }

    // Sign out button
    signoutBtn.addEventListener('click', handleSignOut);

    // Toolbar buttons
    newGameBtn.addEventListener('click', performNewGame);
    undoBtn.addEventListener('click', performUndo);
    redoBtn.addEventListener('click', performRedo);

    // Column Controls
    setupColumnKeyboardNav();

    // Replay Controls
    replayRangeSlider.addEventListener('input', (e) => {
      setReplayStep(parseInt(e.target.value, 10));
    });

    replayPrevBtn.addEventListener('click', () => {
      if (currentReplayStep > 0) setReplayStep(currentReplayStep - 1);
    });

    replayNextBtn.addEventListener('click', () => {
      if (currentReplay && currentReplayStep < currentReplay.moves.length) {
        setReplayStep(currentReplayStep + 1);
      }
    });

    replayCloseXBtn.addEventListener('click', closeReplay);
    replayCloseBottomBtn.addEventListener('click', closeReplay);

    replayModalOverlay.addEventListener('click', (e) => {
      if (e.target === replayModalOverlay) {
        closeReplay();
      }
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && !replayModalOverlay.classList.contains('hidden')) {
        closeReplay();
      }
    });

    // Sync on tab focus / visibility change
    window.addEventListener('focus', syncStateIfVisible);
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') {
        syncStateIfVisible();
      }
    });
  }

  async function syncStateIfVisible() {
    if (!authToken || isActionPending) return;
    const res = await apiRequest('/api/game');
    if (res.status === 401) {
      handleUnauthorized();
      return;
    }
    if (res.ok && res.data) {
      if (res.data.gameState && gameState && res.data.gameState.revision !== gameState.revision) {
        gameState = res.data.gameState;
        archiveData = res.data.archive || archiveData;
        renderAll();
      }
    }
  }

  // Init
  document.addEventListener('DOMContentLoaded', () => {
    setupEvents();
    checkAuthOnLoad();
  });

})();

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// Test DB path
const testDbPath = '/tmp/test_suite_dropline.db';
if (fs.existsSync(testDbPath)) fs.unlinkSync(testDbPath);
process.env.DB_PATH = testDbPath;

const { initDb } = require('./db.js');
const app = require('./server.js');

async function runTests() {
  console.log('--- Starting Comprehensive Test Suite ---');
  const server = app.listen(3002);
  const baseUrl = 'http://localhost:3002';

  try {
    // 1. Health check
    console.log('Test 1: Health check');
    let res = await fetch(`${baseUrl}/api/health`);
    assert.strictEqual(res.status, 200);
    let json = await res.json();
    assert.strictEqual(json.status, 'ok');

    // 2. Static HTML check
    console.log('Test 2: Serve index.html');
    res = await fetch(`${baseUrl}/`);
    assert.strictEqual(res.status, 200);
    let html = await res.text();
    assert.ok(html.includes('DropLine'));
    assert.ok(html.includes('Drop in column 1'));
    assert.ok(html.includes('Drop in column 7'));

    // 3. Unauthenticated request rejected
    console.log('Test 3: Unauthenticated /api/game rejected');
    res = await fetch(`${baseUrl}/api/game`);
    assert.strictEqual(res.status, 401);

    // 4. Invalid credentials rejected
    console.log('Test 4: Invalid signin');
    res = await fetch(`${baseUrl}/api/auth/signin`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'avery@dropline.test', password: 'incorrect' })
    });
    assert.strictEqual(res.status, 401);

    // 5. Sign in Avery Morgan (Seed state check)
    console.log('Test 5: Sign in Avery Morgan');
    res = await fetch(`${baseUrl}/api/auth/signin`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'avery@dropline.test', password: 'password123' })
    });
    assert.strictEqual(res.status, 200);
    const averyAuth = await res.json();
    assert.strictEqual(averyAuth.user.name, 'Avery Morgan');
    assert.strictEqual(averyAuth.user.email, 'avery@dropline.test');
    assert.strictEqual(averyAuth.gameState.revision, 7);
    assert.strictEqual(averyAuth.gameState.redWins, 2);
    assert.strictEqual(averyAuth.gameState.yellowWins, 1);
    assert.strictEqual(averyAuth.gameState.draws, 1);
    assert.strictEqual(averyAuth.gameState.appliedHistory.length, 2);
    assert.strictEqual(averyAuth.gameState.redoHistory.length, 1);
    const averyToken = averyAuth.token;

    // 6. Avery Redo
    console.log('Test 6: Avery performs Redo');
    res = await fetch(`${baseUrl}/api/game/redo`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${averyToken}` },
      body: JSON.stringify({ expectedRevision: 7, operationId: 'avery-op-redo' })
    });
    assert.strictEqual(res.status, 200);
    let stateData = await res.json();
    assert.strictEqual(stateData.gameState.revision, 8);
    assert.strictEqual(stateData.gameState.appliedHistory.length, 3);
    assert.strictEqual(stateData.gameState.redoHistory.length, 0);
    assert.strictEqual(stateData.gameState.currentPlayer, 'Yellow');

    // 7. Avery Undo twice
    console.log('Test 7: Avery performs Undo twice');
    res = await fetch(`${baseUrl}/api/game/undo`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${averyToken}` },
      body: JSON.stringify({ expectedRevision: 8, operationId: 'avery-op-undo-1' })
    });
    assert.strictEqual(res.status, 200);
    stateData = await res.json();
    assert.strictEqual(stateData.gameState.revision, 9);
    assert.strictEqual(stateData.gameState.appliedHistory.length, 2);
    assert.strictEqual(stateData.gameState.redoHistory.length, 1);

    res = await fetch(`${baseUrl}/api/game/undo`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${averyToken}` },
      body: JSON.stringify({ expectedRevision: 9, operationId: 'avery-op-undo-2' })
    });
    assert.strictEqual(res.status, 200);
    stateData = await res.json();
    assert.strictEqual(stateData.gameState.revision, 10);
    assert.strictEqual(stateData.gameState.appliedHistory.length, 1);
    assert.strictEqual(stateData.gameState.redoHistory.length, 2);

    // 8. Sign in Jordan Lee (Account isolation check)
    console.log('Test 8: Sign in Jordan Lee and verify account isolation');
    res = await fetch(`${baseUrl}/api/auth/signin`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: 'jordan@dropline.test', password: 'password123' })
    });
    assert.strictEqual(res.status, 200);
    const jordanAuth = await res.json();
    assert.strictEqual(jordanAuth.user.name, 'Jordan Lee');
    assert.strictEqual(jordanAuth.gameState.revision, 4);
    assert.strictEqual(jordanAuth.gameState.redWins, 1);
    assert.strictEqual(jordanAuth.gameState.yellowWins, 2);
    assert.strictEqual(jordanAuth.gameState.draws, 0);
    assert.strictEqual(jordanAuth.archive.totalCount, 11);
    assert.strictEqual(jordanAuth.archive.matches.length, 10); // latest 10
    const jordanToken = jordanAuth.token;

    // 9. Concurrency test in Jordan account: Stale revision rejected with 409
    console.log('Test 9: Stale revision in Jordan account');
    res = await fetch(`${baseUrl}/api/game/move`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
      body: JSON.stringify({ column: 3, expectedRevision: 2, operationId: 'jordan-stale' })
    });
    assert.strictEqual(res.status, 409);
    let conflictData = await res.json();
    assert.strictEqual(conflictData.message, 'Game updated in another tab');
    assert.strictEqual(conflictData.gameState.revision, 4);

    // 10. Valid move in Jordan account
    console.log('Test 10: Valid move in Jordan account');
    res = await fetch(`${baseUrl}/api/game/move`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
      body: JSON.stringify({ column: 3, expectedRevision: 4, operationId: 'jordan-move-1' })
    });
    assert.strictEqual(res.status, 200);
    stateData = await res.json();
    assert.strictEqual(stateData.gameState.revision, 5);
    assert.strictEqual(stateData.gameState.currentPlayer, 'Red');

    // 11. Full column test
    console.log('Test 11: Column full detection');
    // Jordan's col 3 now has some pieces. Let's fill column 1 completely (6 pieces)
    let curRev = 5;
    for (let i = 0; i < 6; i++) {
      res = await fetch(`${baseUrl}/api/game/move`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
        body: JSON.stringify({ column: 1, expectedRevision: curRev, operationId: `fill-col1-${i}` })
      });
      assert.strictEqual(res.status, 200);
      stateData = await res.json();
      curRev = stateData.gameState.revision;
    }
    // Now drop in column 1 again (7th piece) -> Should fail with 400
    res = await fetch(`${baseUrl}/api/game/move`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
      body: JSON.stringify({ column: 1, expectedRevision: curRev, operationId: 'fill-col1-overflow' })
    });
    assert.strictEqual(res.status, 400);
    let errData = await res.json();
    assert.strictEqual(errData.message, 'Column 1 is full');
    assert.strictEqual(errData.gameState.revision, curRev); // Revision unchanged!

    // 12. New Game in Jordan account
    console.log('Test 12: New game preserves totals and archive');
    res = await fetch(`${baseUrl}/api/game/new`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
      body: JSON.stringify({ expectedRevision: curRev, operationId: 'jordan-new-game' })
    });
    assert.strictEqual(res.status, 200);
    stateData = await res.json();
    curRev = stateData.gameState.revision;
    assert.strictEqual(stateData.gameState.appliedHistory.length, 0);
    assert.strictEqual(stateData.gameState.redoHistory.length, 0);
    assert.strictEqual(stateData.gameState.currentPlayer, 'Red');
    assert.strictEqual(stateData.gameState.status, 'active');
    assert.strictEqual(stateData.gameState.redWins, 1);
    assert.strictEqual(stateData.gameState.yellowWins, 2);
    assert.strictEqual(stateData.archive.totalCount, 11);

    // 13. Win game, check score increment & archive addition, then undo and redo win
    console.log('Test 13: Win game, archive, undo win, redo win');
    // Play a 7-move horizontal win on row 6:
    // Moves: R1, Y1, R2, Y2, R3, Y3, R4 -> Red wins!
    const winMoves = [1, 1, 2, 2, 3, 3, 4];
    for (const col of winMoves) {
      res = await fetch(`${baseUrl}/api/game/move`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
        body: JSON.stringify({ column: col, expectedRevision: curRev, operationId: `win-move-${col}-${curRev}` })
      });
      assert.strictEqual(res.status, 200);
      stateData = await res.json();
      curRev = stateData.gameState.revision;
    }
    assert.strictEqual(stateData.gameState.status, 'Red wins');
    assert.strictEqual(stateData.gameState.redWins, 2); // 1 + 1 = 2
    assert.strictEqual(stateData.archive.totalCount, 12); // 11 + 1 = 12
    assert.strictEqual(stateData.archive.matches[0].result, 'Red wins');

    // Undo winning move
    res = await fetch(`${baseUrl}/api/game/undo`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
      body: JSON.stringify({ expectedRevision: curRev, operationId: `undo-win-${curRev}` })
    });
    assert.strictEqual(res.status, 200);
    stateData = await res.json();
    curRev = stateData.gameState.revision;
    assert.strictEqual(stateData.gameState.status, 'active');
    assert.strictEqual(stateData.gameState.redWins, 1); // decremented back to 1
    assert.strictEqual(stateData.archive.totalCount, 11); // removed from archive

    // Redo winning move
    res = await fetch(`${baseUrl}/api/game/redo`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${jordanToken}` },
      body: JSON.stringify({ expectedRevision: curRev, operationId: `redo-win-${curRev}` })
    });
    assert.strictEqual(res.status, 200);
    stateData = await res.json();
    curRev = stateData.gameState.revision;
    assert.strictEqual(stateData.gameState.status, 'Red wins');
    assert.strictEqual(stateData.gameState.redWins, 2); // incremented back to 2
    assert.strictEqual(stateData.archive.totalCount, 12); // restored to archive

    // 14. Multi-tab Sign-out revocation
    console.log('Test 14: Multi-tab Sign-out revocation');
    res = await fetch(`${baseUrl}/api/auth/signout`, {
      method: 'POST',
      headers: { 'Authorization': `Bearer ${jordanToken}` }
    });
    assert.strictEqual(res.status, 200);

    // Another request with jordanToken must now fail with 401
    res = await fetch(`${baseUrl}/api/game`, {
      headers: { 'Authorization': `Bearer ${jordanToken}` }
    });
    assert.strictEqual(res.status, 401);

    console.log('--- ALL TESTS PASSED! ---');
  } finally {
    server.close();
    if (fs.existsSync(testDbPath)) fs.unlinkSync(testDbPath);
  }
}

runTests().catch(err => {
  console.error('Test Suite Failure:', err);
  process.exit(1);
});

